// W4 writes an answer, or saves one as a Gmail DRAFT. It has no node that sends email.
const b = $json.body || {};
const action = String(b.action || '');
const NL = String.fromCharCode(10);
if (action === 'draft') {
  const text = String(b.text || '').trim();
  const thread = String(b.thread_id || '').trim();
  if (!/^[0-9a-f]+$/i.test(thread)) throw new Error('thread_id is missing or malformed');
  if (!text) throw new Error('the answer is empty');
  if (text.length > 6000) throw new Error('the answer is too long');
  if (text.includes('[') && text.includes(']')) throw new Error('the answer still has [placeholders] to fill in');
  return [{ json: { action, thread_id: thread, text } }];
}
if (action !== 'write') throw new Error('action must be write or draft');
for (const k of ['their_message', 'my_name']) if (!String(b[k] || '').trim()) throw new Error(k + ' is missing');
const system = [
  'You draft short email replies for a job seeker, written as the job seeker, in the first person.',
  'Rules:',
  '- Answer exactly what the recruiter asked or proposed. Warm, professional, brief: 40 to 120 words.',
  '- Never invent facts. Times, dates, availability, salary, notice period, links and numbers come only from the notes below. If the reply needs one that is not in the notes, write a short placeholder in square brackets instead, for example [two times that suit you].',
  '- No subject line. Start with a greeting that uses their first name if it is known.',
  '- End with "Best regards," and the name of the job seeker on the next line. Nothing after that.',
  '- Plain text only: no markdown, no bullet points unless they asked several questions.',
].join(NL);
const user = [
  'Recruiter: ' + (b.their_name || 'unknown') + ' at ' + (b.company || 'the company') + '.',
  'Role the job seeker wrote about: ' + (b.role || 'not given') + '.',
  'Job seeker: ' + b.my_name + '.',
  '',
  'Their email:',
  String(b.their_message).slice(0, 4000),
  '',
  'The job seeker\'s earlier email to them:',
  String(b.my_email || '(not available)').slice(0, 3000),
  '',
  'Notes from the job seeker for this answer (facts that may be used): ' + (String(b.notes || '').trim() || 'none'),
].join(NL);
return [{ json: { action, model: 'gpt-oss:120b',
                  messages: [{ role: 'system', content: system }, { role: 'user', content: user }] } }];

const r = $input.first().json;
const raw = String(r.message?.content || '').trim();
if (!raw) return [{ json: { error: 'the model gave no answer ' + JSON.stringify(r.error || '').slice(0, 150) } }];
const NL = String.fromCharCode(10);
const text = raw.split(NL).filter(l => !l.trim().toLowerCase().startsWith('subject:')).join(NL).trim();
return [{ json: { text, model: r.model || 'gpt-oss:120b' } }];

// The draft answers their last message in the same Gmail thread, addressed to whoever wrote it.
const req = $('Check request').first().json;
const thread = $input.first().json;
if (thread.error || !thread.messages) {
  return [{ json: { error: 'Gmail could not read the thread: ' + JSON.stringify(thread.error || thread).slice(0, 200) } }];
}
const header = (m, name) => {
  for (const h of (m.payload?.headers || [])) if (String(h.name).toLowerCase() === name) return String(h.value || '');
  return '';
};
const addr = s => {
  const t = String(s || '');
  const o = t.indexOf('<'), c = t.indexOf('>');
  return (o >= 0 && c > o ? t.slice(o + 1, c) : t).trim();
};
const msgs = thread.messages;
const theirs = msgs.filter(m => !(m.labelIds || []).includes('SENT'));
if (!theirs.length) return [{ json: { error: 'there is no message from them in this thread' } }];
const last = theirs[theirs.length - 1];
const to = addr(header(last, 'reply-to') || header(last, 'from'));
const messageId = header(last, 'message-id');
let subject = header(last, 'subject') || header(msgs[0], 'subject');
if (!subject.toLowerCase().startsWith('re:')) subject = 'Re: ' + subject;
const CR = String.fromCharCode(13), NL = String.fromCharCode(10), CRLF = CR + NL;
const b64 = s => Buffer.from(s, 'utf8').toString('base64');
const word = s => '=?UTF-8?B?' + b64(s) + '?=';
const wrap = s => { const out = []; for (let i = 0; i < s.length; i += 76) out.push(s.slice(i, i + 76)); return out.join(CRLF); };
const body = req.text.split(CR).join('').split(NL).join(CRLF);
const lines = ['To: ' + to, 'Subject: ' + word(subject)];
if (messageId) lines.push('In-Reply-To: ' + messageId, 'References: ' + messageId);
const mime = lines.concat(['MIME-Version: 1.0', 'Content-Type: text/plain; charset=UTF-8',
                           'Content-Transfer-Encoding: base64', '', wrap(b64(body))]).join(CRLF);
const raw = b64(mime).split('+').join('-').split('/').join('_').replace(/=+$/, '');
return [{ json: { raw, threadId: thread.id, to } }];

const r = $input.first().json;
if (r.error || !r.id) {
  return [{ json: { error: 'Gmail did not save the draft: ' + JSON.stringify(r.error || r).slice(0, 200) } }];
}
return [{ json: { draft_id: r.id, to: $('Build draft').first().json.to } }];
